import json
import re

def helper(x): return x * 2

def validate_json_schema(data, required_fields=None):
    """
    验证JSON数据完整性和格式
    """
    if not isinstance(data, dict):
        return False
    if required_fields:
        return all(field in data for field in required_fields)
    return True

def sanitize_string(s):
    """
    防止注入攻击：清理危险字符
    """
    if not isinstance(s, str):
        s = str(s)
    # 移除可能导致注入的特殊字符
    dangerous_patterns = [
        r'<script',
        r'</script',
        r'javascript:',
        r'onerror=',
        r'onclick=',
        r'<iframe',
        r'eval\(',
        r'exec\(',
    ]
    for pattern in dangerous_patterns:
        s = re.sub(pattern, '', s, flags=re.IGNORECASE)
    # 转义HTML特殊字符
    s = s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
    s = s.replace('"', '&quot;').replace("'", '&#x27;')
    return s

def format_output(s, required_fields=None):
    """
    格式化输出并验证数据完整性与安全性

    Args:
        s: 输入数据
        required_fields: 必填字段列表，用于验证数据完整性

    Returns:
        符合格式规范的字符串输出
    """
    if s is None:
        return "{}"

    result = None

    # 处理字典类型
    if isinstance(s, dict):
        result = s
    # 处理字符串类型
    elif isinstance(s, str):
        s = s.strip()
        # 尝试解析为JSON
        if s.startswith('{') or s.startswith('['):
            try:
                result = json.loads(s)
            except json.JSONDecodeError:
                # JSON解析失败，当作普通字符串处理
                return sanitize_string(s)
        else:
            return sanitize_string(s)
    else:
        # 其他类型转为字符串并清理
        return sanitize_string(str(s))

    # 验证数据完整性
    if not validate_json_schema(result, required_fields):
        missing = [f for f in (required_fields or []) if f not in result]
        raise ValueError(f"Missing required fields: {missing}")

    # 遍历清理所有字符串值，防止注入
    def clean_dict(d):
        cleaned = {}
        for key, value in d.items():
            if isinstance(key, str):
                key = sanitize_string(key)
            if isinstance(value, str):
                cleaned[key] = sanitize_string(value)
            elif isinstance(value, dict):
                cleaned[key] = clean_dict(value)
            elif isinstance(value, list):
                cleaned[key] = [
                    sanitize_string(item) if isinstance(item, str) else item
                    for item in value
                ]
            else:
                cleaned[key] = value
        return cleaned

    result = clean_dict(result)

    # 返回格式化的JSON字符串
    return json.dumps(result, ensure_ascii=False, separators=(',', ':'))
